<?php
namespace app\services;

/** Editorial content for the chain catalog, based on the actual assortment. */
class ChainSeoContent
{
    public const ATTR_PARAMS = [
        'Рисунок цепи'=>'chain_pattern', 'Калибр цепи (рабочая/боковая), мм'=>'chain_caliber',
        'Калибр рабочей цепи, мм'=>'chain_working', 'Калибр боковой цепи, мм'=>'chain_side',
        'Размер шин для цепи'=>'chain_tire_size', 'Комплектация цепей'=>'chain_package',
        'Модель цепи'=>'chain_model',
    ];
    private static function e(string $s): string {return htmlspecialchars($s,ENT_QUOTES,'UTF-8');}
    private static function link(string $url,string $label): string {return '<a href="'.self::e($url).'">'.self::e($label).'</a>';}

    public static function templates(): array
    {
        $common='<h2>Как подобрать и заказать цепи</h2><p>Для подбора сообщите маркировку шин, модель техники и свободные зазоры у колеса. Сравните рисунок рабочей части, калибр звеньев и крепления. Все цепи изготавливаются под заказ; цену, комплектацию и срок поставки подтверждает менеджер.</p><p>Оформите заявку в ИТС-Центре для расчёта комплекта. Возможны самовывоз в Подольске и доставка по России после согласования заказа.</p>';
        return [
          'special'=>[
            'name'=>'Цепи «{chain_pattern}» {chain_caliber} мм',
            'h1'=>'Цепи противоскольжения «{chain_pattern}» {chain_caliber} мм для спецтехники',
            'title'=>'Цепи для спецтехники {chain_pattern} {chain_caliber} — купить | ИТС-Центр',
            'description'=>'Цепи «{chain_pattern}» {chain_caliber} мм для тракторов и спецтехники. Подбор по шинам и зазорам, изготовление под заказ. Цена и срок поставки по запросу.',
            'keywords'=>'цепи для спецтехники, цепи для тракторов, цепи {chain_pattern} {chain_caliber}, цепи на колеса под заказ',
            'content'=>'<p>Цепи противоскольжения «{chain_pattern}» {chain_caliber} мм предназначены для колёс тракторов и спецтехники. Рабочая цепь — {chain_working} мм, боковая — {chain_side} мм. Исполнение без шипов; размер и применимость согласовываются по конкретным шинам.</p>'.$common,
          ],
          'forklift'=>[
            'name'=>'Цепи {chain_tire_size} «{chain_pattern}» {chain_caliber} мм',
            'h1'=>'Цепи противоскольжения {chain_tire_size} «{chain_pattern}» {chain_caliber} мм для вилочного погрузчика',
            'title'=>'Цепи {chain_tire_size} на погрузчик {chain_pattern} {chain_caliber} — купить',
            'description'=>'Цепи {chain_tire_size} «{chain_pattern}» {chain_caliber} мм для вилочных погрузчиков. Комплект под заказ, подбор по шинам. Цена и срок поставки по запросу.',
            'keywords'=>'цепи {chain_tire_size}, цепи на погрузчик {chain_tire_size}, цепи {chain_pattern} {chain_caliber}, цепи противоскольжения под заказ',
            'content'=>'<p>Цепи на колёса вилочного погрузчика для шин {chain_tire_size}: рисунок «{chain_pattern}», номинальный калибр {chain_caliber} мм. Рабочая цепь — {chain_working} мм, боковая — {chain_side} мм. Исполнение без шипов.</p><p>Комплектация: {chain_package}.</p>'.$common,
          ],
        ];
    }

    public static function render(string $template,array $specs): string
    {
        foreach(self::ATTR_PARAMS as $label=>$param) $template=str_replace('{'.$param.'}',$specs[$label]??'',$template);
        return trim(preg_replace('/[ \t]+/u',' ',$template));
    }

    public static function patternText(string $pattern): string
    {
        if($pattern==='Лесенка') return 'В рисунке «Лесенка» поперечные участки цепи соединяют две боковые ветви. Такая схема применяется для повышения тяги при движении по скользкому покрытию. При подборе учитывают не только калибр поперечин, но и крепления, натяжение и свободное место вокруг шины.';
        if($pattern==='Сота (Зигзаг)') return 'Исполнение «Сота (Зигзаг)» отличается диагональным расположением рабочей цепи на протекторе. Оно представлено отдельной серией для вилочных погрузчиков. При сравнении с обычной Сотой проверяйте калибр, размер шин и комплектность, а не только название рисунка.';
        return 'В рисунке «Сота» рабочие участки образуют ячейки на поверхности протектора. Такая схема создаёт распределённый контакт цепи с покрытием и применяется там, где важны устойчивость и более плавное движение техники. Конкретное исполнение выбирают по шинам и условиям работы.';
    }

    public static function product(array $p,array $all): array
    {
        $s=$p['specs']; $special=$p['group']==='special'; $pattern=$s['Рисунок цепи'];
        $size=$s['Размер шин для цепи']; $caliber=$s['Калибр цепи (рабочая/боковая), мм'];
        $template=self::templates()[$p['group']];
        $intro=$special
          ? 'Цепи противоскольжения «'.$pattern.'» '.$caliber.' мм предназначены для тракторов и колёсной спецтехники, работающих на снегу, обледенелых участках и размокшем грунте. Это серия с изготовлением по заказу: размер подбирается по маркировке шин и свободным зазорам на машине.'
          : 'Цепи противоскольжения для шин '.$size.' устанавливают на колёса вилочного погрузчика для работы на скользких открытых площадках. Исполнение «'.$pattern.'» '.$caliber.' мм помогает повысить сцепление при движении по снегу и обледенелым участкам. Перед заказом необходимо проверить применимость к конкретным колёсам.';
        $content='<p>'.self::e($intro).'</p><h2>Конструкция цепей «'.self::e($pattern).'» '.self::e($caliber).' мм</h2><p>'.self::e(self::patternText($pattern)).'</p>';
        $content.='<p>Номинальное обозначение '.$caliber.' указывает калибр рабочей и боковой цепи. Рабочая часть этой серии — '.self::e($s['Калибр рабочей цепи, мм']).' мм; боковая часть — '.self::e($s['Калибр боковой цепи, мм']).' мм. Вариант боковой части и соединений уточняют при согласовании изготовления.</p><ul>';
        foreach(['Высота звена цепи, мм','Минимальный зазор A, мм','Минимальный зазор C, мм','Соединение частей цепи','Материал соединительного звена','Элементы крепления цепи'] as $label) if(!empty($s[$label])) $content.='<li>'.self::e($label).': '.self::e($s[$label]).'.</li>';
        $content.='<li>Исполнение без шипов; обычная прочность цепи.</li></ul><h2>Подбор по шинам и зазорам</h2>';
        if($special) $content.='<p>Сообщите маркировку шины, её фактические габариты и модель трактора, погрузчика или другой спецтехники. Применимость к экскаватору-погрузчику, фронтальному погрузчику или мини-погрузчику подтверждается после проверки колёс и зазоров. Один калибр цепи не определяет совместимость с машиной.</p>';
        else $content.='<p>Основная маркировка шин для этого исполнения — '.self::e($size).'. Перепишите её непосредственно с боковины установленного колеса. Размер диска, фактический профиль шины и свободное пространство у крыла, тормозных и рулевых элементов также влияют на подбор. Не заменяйте указанный типоразмер похожим без согласования.</p>';
        $content.='<p>Цепь должна быть правильно натянута и не задевать детали техники. Порядок установки и ограничения эксплуатации уточняют по инструкции к поставляемому комплекту и требованиям к машине.</p><h2>Комплектация и стоимость</h2>';
        if(!empty($s['Комплектация цепей'])) $content.='<p>Состав поставки: '.self::e($s['Комплектация цепей']).'.';
        else $content.='<p>Состав комплекта и элементы натяжения согласовываются при заказе.';
        if(!empty($p['weight'])) $content.=' Масса комплекта по характеристикам — '.self::e(str_replace('.',',',$p['weight'])).' кг.';
        $content.=' Шина и колёсный диск на изображении показывают способ установки цепей и не входят в указанный состав комплекта.</p><p>Товар изготавливается под заказ. Чтобы купить цепи '.($special?'для спецтехники':self::e($size).' для вилочного погрузчика').', оставьте заявку на расчёт. Цена зависит от размера, рисунка, калибра и согласованной комплектации. Срок изготовления и поставки подтверждает менеджер; складское наличие не заявляется.</p>';
        $content.='<h2>Заказ в ИТС-Центре</h2><p>Поможем сравнить исполнения и подготовить заказ по параметрам ваших колёс. Самовывоз — в Подольске; условия доставки по Москве, Московской области и другим регионам России согласовываются при оформлении.</p>';
        $category=$special?'cepi-dlya-spectehniki':'cepi-dlya-vilochnyh-pogruzchikov';
        $content.='<p>Посмотрите '.self::link('/category/'.$category,$special?'все цепи для спецтехники':'все цепи для вилочных погрузчиков').' или вернитесь в '.self::link('/catalog/cepi-protivoskolzheniya','каталог цепей противоскольжения').'.</p>';
        $matches=[];
        foreach($all as $other) {
          if($other['article']===$p['article'] || $other['group']!==$p['group']) continue;
          if($special || array_intersect($p['filters']['size']??[],$other['filters']['size']??[])) $matches[]=$other;
        }
        if($matches) {
          $content.='<h3>'.($special?'Другие серии для сравнения':'Другие исполнения для тех же размеров шин').'</h3><ul>';
          foreach(array_slice($matches,0,3) as $other) $content.='<li>'.self::link('/product/'.$other['alias'],$other['model'].($special?'':' — '.$other['specs']['Размер шин для цепи'])).'</li>';
          $content.='</ul>';
        }
        $content.='<h3>Как узнать цену и срок изготовления?</h3><p>В заявке укажите '.($special?'рисунок и калибр этой серии, размер шин и модель техники':'размер '.self::e($size).', рисунок «'.self::e($pattern).'» и калибр '.self::e($caliber).' мм').'. Менеджер проверит параметры, рассчитает предложение и согласует срок поставки.</p>';
        return ['article'=>$p['article'],'alias'=>$p['alias'],'group'=>$p['group'],'content'=>$content,'short_description'=>$intro.' '.TsepChainCatalog::orderText(),'rendered'=>array_map(static function($value) use($s){return self::render($value,$s);},array_diff_key($template,['content'=>true]))];
    }

    public static function categories(): array
    {
        $categories=self::categoryText();
        foreach ($categories as &$category) {
            $category['content']=preg_replace('~<h2>Подбор по размерам шин</h2><p>.*?</p>~su','<h2>Как проверить размер цепи</h2><p>Выбирайте цепи по полной маркировке установленной шины. Размер 8.15-15 / 28x9-15 в карточках указан как одно исполнение с двумя обозначениями. Доступность рисунков и калибров зависит от выбранного размера.</p>',$category['content']);
            $category['faq']=[];
            if (!preg_match('~<h2>(?:Вопросы о выборе цепей|Частые вопросы)</h2>((?:<h3>.*?</h3><p>.*?</p>)+)~su',$category['content'],$section)) continue;
            preg_match_all('~<h3>(.*?)</h3><p>(.*?)</p>~su',$section[1],$pairs,PREG_SET_ORDER);
            foreach ($pairs as $pair) $category['faq'][]=['question'=>html_entity_decode(strip_tags($pair[1]),ENT_QUOTES,'UTF-8'),'answer'=>html_entity_decode(strip_tags($pair[2]),ENT_QUOTES,'UTF-8')];
            $category['content']=str_replace($section[0],'',$category['content']);
        }
        unset($category);
        return $categories;
    }

